-- Reconferência delimitada, sem alterar a data global de vigência.
-- Corrige o escopo das Normas aprovadas: os números não pertencem ao corpo principal.
update public.dispositivos d set referencia='Normas, '||d.referencia,
 metadata=d.metadata||jsonb_build_object('referencia_anterior_curadoria',d.referencia)
from public.normas n where n.id=d.norma_id and n.titulo='Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021' and d.referencia like 'Art.%';
update public.dispositivos d set referencia='Normas, art. 14, caput e §§ 1º a 3º'
from public.normas n where n.id=d.norma_id and n.titulo='Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021' and d.referencia='Normas, Art. 14 e §§';
update public.dispositivos d set referencia='Normas, art. 6º — texto completo'
from public.normas n where n.id=d.norma_id and n.titulo='Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021' and d.referencia='Normas, art. 6º, incisos I a III';
-- Padroniza somente a caixa do Art. na referência da Portaria 213.
update public.dispositivos d set referencia=replace(d.referencia,'Normas, Art.','Normas, art.')
from public.normas n where n.id=d.norma_id and n.titulo='Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021' and d.referencia like 'Normas, Art.%';
with entrada as (
 select * from jsonb_to_recordset($curadoria$[{"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 10, caput e § 1º", "artigo": "10", "paragrafo": null, "texto": "Art. 10 As armas de fogo importadas deverão estar marcadas de maneira que permitam a identificação da empresa importadora, conforme previsto na alínea “b”, do nº 1, do art. 6º, do Decreto Legislativo nº 3.229, de 29 de outubro de 1999, além das marcações estabelecidas no art. 4º, destas normas. §1º Admite-se a execução de marcações no Brasil, desde que solicitado previamente pela empresa importadora ao Comando Logístico e que o serviço seja realizada por pessoa física ou jurídica especializada, devendo a arma possuir ao menos as seguintes marcações de fábrica: I- número de série na armação; II- o ano de fabricação quando não estiver incluído no sistema de numeração serial; e III- nome do fabricante.", "pagina": 6, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 10, § 2º", "artigo": "10", "paragrafo": "2", "texto": "§2º O armamento somente poderá ser comercializado pela empresa importadora após realizadas as marcações previstas nestas normas e mediante a autorização do órgão de vinculação do Sistema de Fiscalização de Produtos Controlados (SisFPC).", "pagina": 6, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 10, § 3º", "artigo": "10", "paragrafo": "3", "texto": "§3º Em caso de descumprimento das marcações mínimas do §1º, a liberação alfandegária somente será procedida para reexportação ao país de origem.", "pagina": 6, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 14, caput e §§ 1º a 3º", "artigo": "14", "paragrafo": null, "texto": "Art. 14 O Comando Logístico, por intermédio da DFPC, poderá autorizar a remarcação de armas de fogo cuja identificação e marcações tenham sido suprimidas ou adulteradas. §1º A solicitação de remarcação deverá ser acompanhada de laudo pericial emitido por órgão de criminalística, laboratório técnico particular ou instituição de estudos e pesquisas criminais que possam recuperar integralmente os dados da marcação original. §2º A remarcação deverá ser feita pelo fabricante, para armas fabricadas no País, ou em empresa ou profissional especializado, no caso das armas importadas, mediante autorização da Administração Militar. §3º A remarcação referida no parágrafo anterior deve seguir a mesma marcação original, devendo ter a profundidade de 0,10mm, admitindo-se uma tolerância de mais ou menos 0,02mm.", "pagina": 8, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 16, caput e §§ 1º a 3º", "artigo": "16", "paragrafo": null, "texto": "Art. 16 Os fabricantes, as pessoas jurídicas importadoras e os comerciantes deverão criar e manter um banco de dados próprio que assegure, a partir da documentação de regularização, fabricante, tipo, calibre e número de série da arma de fogo, as seguintes informações: I – dados de identificação do adquirente (nome, Identidade, CNPJ/CPF, endereço e filiação); II – autorização de aquisição emitida pelo Comando do Exército ou pelo Sistema Nacional de Armas (SINARM); III – dados da nota fiscal; IV– dados da Licença de Importação ou Licença Simplificada de Importação, quando for o caso; e V – número da guia de tráfego eletrônica, se for o caso. §1º Os fabricantes, as pessoas jurídicas importadoras e os comerciantes de armas de fogo disponibilizarão ao Comando do Exército, por intermédio da DFPC, e para a Polícia Federal, as informações do banco de dados tratado no caput. §2º Os registros de armas de fogo deverão ser mantidos por um período mínimo de 20 (vinte) anos. §3º O cadastro dos dados referentes às características das impressões de raiamento e de microestriamento do projétil disparado (alínea “k” do inciso I, do art. 5º do Decreto nº 9.847, de 25 de junho de 2019), fornecidos pelo fabricante, será normatizado a partir da disponibilização dessa funcionalidade pelo banco de dados do SIGMA e deverá ser compartilhado ao novo Banco Nacional de Perfis Balísticos, criado pela Lei Anticrime (Lei 13.964, de 24 de dezembro de 2019).", "pagina": 9, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 17", "artigo": "17", "paragrafo": null, "texto": "Art. 17. A DFPC fará o controle do cadastro precário das armas de fogo fabricadas ou importadas por meio da inserção dos dados no SICOFA, mediante o envio mensal das informações pelos fabricantes, por ocasião da finalização do processo de fabricação e destinação, e pelas pessoas jurídicas importadoras, por ocasião da anuência do processo de importação.", "pagina": 9, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 213-COLOG - marc_armas.pdf", "referencia": "Normas, art. 6º", "artigo": "6", "paragrafo": null, "texto": "Art. 6º Cada fabricante ou importador deverá informar à Diretoria de Fiscalização de Produtos Controlados (DFPC) o padrão serial utilizado para a marcação de suas armas de fogo e suas peças.", "pagina": 5, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 214 - COLOG, de 15 de setembro de 2021.pdf", "referencia": "Normas, art. 2º", "artigo": "2", "paragrafo": null, "texto": "Art. 2º Todas as munições e seus insumos, comercializadas no Brasil, oriundas de fabricantes nacionais ou importadas, deverão estar acondicionadas até seu consumo, em embalagens gravadas com sistema de código unidimensional ou bidimensional, que permita a identificação do fabricante, comerciante (lojista ou importador), lote, código de rastreabilidade, calibre e quantidade. §1º Admite-se que os estojos de munição reaproveitados para recarga não estejam acondicionados em suas embalagens gravadas de acordo com o caput. §2º Admite-se para munições e seus insumos, importados que não possuam identificação de fábrica em suas embalagens, o uso de etiquetas ou rótulos adicionados resistentes à umidade e com durabilidade, contendo informações do caput. §3º O código unidimensional ou bidimensional a que se refere o caput deverá estar de acordo com as especificações das normas de rastreamento do SisFPC, e ainda, permitir a recuperação das informações em banco de dados próprios do fabricante ou do comércio, que registrará as informações de qualificação do adquirente. §4º Os fabricantes ou pessoas jurídicas importadoras de munição e seus insumos deverão inserir os dados de identificação das embalagens no Sistema de Rastreamento de Embalagem de Munição (SIREM). §5º A inserção de dados de que trata o parágrafo anterior será de caráter obrigatório a partir da disponibilização do correspondente módulo do SIREM no SisGCorp.", "pagina": 4, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 214 - COLOG, de 15 de setembro de 2021.pdf", "referencia": "Normas, art. 4º", "artigo": "4", "paragrafo": null, "texto": "Art. 4º Toda munição e seus insumos, destinadas para os órgãos, instituições e entidades a seguir discriminadas, deverá conter código de rastreabilidade de munição gravado na base dos estojos, o qual permita identificar o fabricante, o lote e o órgão adquirente, em cumprimento ao que determina o § 2º do art. 23 da Lei nº 10.826, de 22 de dezembro de 2003: I - Forças Armadas; II - Polícia Federal; III - Polícia Rodoviária Federal; IV - Polícia Ferroviária Federal; V - Polícias Civis; VI- Polícias Militares e Corpos de Bombeiros Militares; VII - Polícias Penais Federal, Estaduais e Distrital; VIII – Força Nacional de Segurança Pública (FNSP) IX - Guardas Municipais; X - Guardas Portuárias XI- Agência Brasileira de Inteligência (ABIN) XII - Departamento de Segurança do Gabinete de Segurança Institucional da Presidência da República; XIII- Policias Legislativas; XIV- Receita Federal do Brasil; XV – Poder Judiciário Federal ou Estadual; XVI - Ministérios Públicos da União e dos Estados; XVII - Conselho Nacional de Justiça (CNJ) e Conselho Nacional do Ministério Público (CNMP); XVIII - outros órgãos públicos autorizados ao uso de armas de fogo em suas atividades, previstos em legislação própria; e §1º Admite-se marcação no corpo do estojo quando da impossibilidade de marcação prevista no caput. §2º O disposto no caput não alcança as munições dos armamentos pesados definidos pela Portaria nº 118 –COLOG, de 2019, que apresenta a relação dos Produtos Controlados pelo Exército.", "pagina": 4, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 214 - COLOG, de 15 de setembro de 2021.pdf", "referencia": "Normas, art. 6º — texto completo", "artigo": "6", "paragrafo": null, "texto": "Art. 6º O lote rastreável de munição adquirido pelos órgãos referidos no art. 4º, deverá atender aos seguintes requisitos: I – incluir apenas munição de mesmo calibre e tipo, exceto no caso de munição elada, cujo lote poderá conter munições de tipos diferentes (exemplo: elos de munição comum permeados com munição traçante); II – ser marcado com um único código de rastreabilidade no corpo do estojo; e III – ser comercializado somente para um órgão específico. §1º Admite-se a marcação no corpo do estojo quando da impossibilidade de marcação prevista no inciso II. §2º Os fabricantes ou pessoas jurídicas importadoras de munição deverão inserir, mensalmente, os dados de lote rastreável no Sistema de Identificação Personalisada de Munições (SIP). §3º A inserção de dados de que trata o parágrafo anterior será de caráter obrigatório a partir da disponibilização do correspondente módulo do SIP no SisGCorp.", "pagina": 6, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 214 - COLOG, de 15 de setembro de 2021.pdf", "referencia": "Normas, art. 9º, caput e §§ 1º a 4º", "artigo": "9", "paragrafo": null, "texto": "Art. 9º Os fabricantes, as pessoas jurídicas importadoras e os comerciantes deverão manter, em banco de dados próprio, os registros de controle de entradas e saídas de munição, contendo os seguintes dados: I – número do adquirente junto ao Exército; II – dados do adquirente (nome, CPF ou CNPJ, endereço e filiação); III – número de autorização de aquisição emitida pelo Comando do Exército ou Polícia Federal, quando for o caso; IV – código do produto; V – código de rastreabilidade, se for o caso; VI - lote da munição; VII – descrição da munição; VIII – número do certificado de registro de arma de fogo (CRAF); IX – número da nota fiscal ou Licença de Importação; e X – quantidade comercializada. §1º Os fabricantes, importadores comerciais e os comércios atacadistas e varejistas disponibilizarão ao Sistema de Fiscalização de Produtos Controlados (SisFPC), o acesso às informações ao seu banco de dados, na forma de leitura. §2º Também serão disponibilizados ao Sistema Nacional de Informações de Segurança Pública, Prisionais e de Rastreabilidade de Armas e Munições, de Materail Genético, de Digitais e de Drogas (SINESP) o acesso aos dados de interesse do sistema para fins de rastreamento de munição. §3º Os órgãos da Administração Pública e as entidades disponibilizarão ao SINESP o acesso aos dados de interesse do sistema para fins de rastreamento de munição, nos termos do art. 37 da Lei nº 13.675, de 11 de junho de 2018. §4º Os registros de que trata o caput deverão ser mantidos por um período mínimo de 20 (vinte) anos à disposição da Administração Militar e demais órgãos de investigação policial.", "pagina": 6, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 214 - COLOG, de 15 de setembro de 2021.pdf", "referencia": "Normas, art. 10, caput e §§ 1º a 5º", "artigo": "10", "paragrafo": null, "texto": "Art 10 Os fabricantes, as pessoas jurídicas importadoras e os comerciantes deverão manter, em banco de dados próprio, os registros de controle de entradas e saídas de insumos de munição, contendo os seguintes dados: I – número do registro do adquirente junto ao Exército; II – dados do adquirente (nome, CPF ou CNPJ, endereço e filiação); III – número de autorização de aquisição emitida pelo Comando do Exército ou Polícia Federal, quando for o caso; IV – código do produto; V – descrição de insumos; VI – número do certificado de registro de arma de fogo (CRAF), quando for o caso; VII – número da nota fiscal ou Licença de Importação; e VIII – quantidade comercializada. §1º Os insumos de munição que trata o caput são: espoleta para munição de arma de fogo, estojo metálico para munição de arma de fogo (projétil para munição de arma de fogo raiada e pólvoras mecânicas e químicas para recarga de munição (todos previstos na Portaria nº 118-COLOG, de 2019). §2º Os fabricantes, as pessoas jurídicas importadoras e os comerciantes disponibilizarão ao Sistema de Fiscalização de Produtos Controlados (SisFPC), o acesso às informações ao seu banco de dados , na forma de leitura. §3º Também serão disponibilizados ao Sistema Nacional de Informações de Segurança Pública, Prisionais e de Rastreabilidade de Armas e Munições, de Materail Genético, de Digitais e de Drogas (SINESP) o acesso aos dados de interesse do sistema para fins de rastreamento de insumos de munição. §4º Os órgãos da Administração Pública e as entidades disponibilizarão ao SINESP o acesso aos dados de interesse do sistema para fins de rastreamento de insumos de munição, nos termos do art. 37 da Lei nº 13.675, de 11 de junho de 2018. §5º Os registros de que trata o caput deverão ser mantidos por um período mínimo de 20 (vinte) anos à disposição da Administração Militar e demais órgãos de investigação policial.", "pagina": 7, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "documento": "Portaria 214 - COLOG, de 15 de setembro de 2021.pdf", "referencia": "Normas, art. 11", "artigo": "11", "paragrafo": null, "texto": "Art. 11 Os fabricantes, as pessoas jurídicas importadoras e os comerciantes deverão ainda cadastrar e atualizar seus estoques de munições e seus insumos no SICOVEM.", "pagina": 8, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "documento": "Portaria 800, de 14 de agosto de 2020 - CNAE.pdf", "referencia": "Art. 1º", "artigo": "1", "paragrafo": null, "texto": "Art. 1º Fica aprovada a tabela de classificação do nível de risco de atividades econômicas sujeitas a ato de liberação por órgãos do Sistema de Fiscalização de Produtos Controlados pelo Exército (SisFPC), conforme o anexo único, desta portaria.", "pagina": 1, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "documento": "Portaria 800, de 14 de agosto de 2020 - CNAE.pdf", "referencia": "Art. 2º", "artigo": "2", "paragrafo": null, "texto": "Art. 2º Fica estabelecido que as atividades econômicas relacionadas a produtos controlados pelo Exército (PCE) não sejam classificadas no nível de risco I.", "pagina": 1, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "documento": "Portaria 800, de 14 de agosto de 2020 - CNAE.pdf", "referencia": "Art. 2º, parágrafo único", "artigo": "2", "paragrafo": "único", "texto": "Parágrafo único. A ausência de classificação no nível de risco I a que se refere o caput, leva em consideração a extensão, a gravidade e o grau de irreparabilidade do impacto causado à sociedade, na hipótese de ocorrência de evento danoso envolvendo algum PCE.", "pagina": 1, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "documento": "Portaria 800, de 14 de agosto de 2020 - CNAE.pdf", "referencia": "Art. 3º", "artigo": "3", "paragrafo": null, "texto": "Art. 3º Fica determinado que a tabela de classificação de risco de que trata o art. 1º seja revista periodicamente para fins de inclusão, exclusão e reclassificação das atividades econômicas sujeitas a ato de liberação por órgãos do SisFPC.", "pagina": 1, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "documento": "Portaria 800, de 14 de agosto de 2020 - CNAE.pdf", "referencia": "Art. 4º", "artigo": "4", "paragrafo": null, "texto": "Art. 4º Esta portaria entra em vigor em 1º de setembro de 2020.", "pagina": 1, "origem": "PDF fornecido pelo usuário — página conferida", "data": "2026-10-08", "observacao": "Espaçamento e caracteres de extração normalizados; conteúdo confrontado com a página do PDF."}]$curadoria$::jsonb)
 as x(norma text,documento text,referencia text,artigo text,paragrafo text,texto text,pagina integer,origem text,data text,pendente boolean,observacao text)
), resolvidos as (
 select n.id norma_id,doc.id documento_id,e.* from entrada e join public.normas n on n.titulo=e.norma
 left join public.documentos doc on doc.nome_arquivo=e.documento
)
insert into public.dispositivos(norma_id,documento_id,referencia,artigo,paragrafo,texto_literal,pagina,status,conferido,metadata,fonte_tipo)
select norma_id,documento_id,referencia,artigo,paragrafo,texto,pagina,
 case when coalesce(pendente,false) then 'vigencia_a_confirmar' else 'vigente' end,
 not coalesce(pendente,false),jsonb_build_object('conferencia_textual',jsonb_build_object(
 'data',data,'origem',origem,'documento',documento,'observacao',observacao)),
 case when documento is null then 'site_oficial' else 'pdf_oficial' end
from resolvidos
on conflict(norma_id,referencia) do update set
 texto_literal=excluded.texto_literal,artigo=excluded.artigo,paragrafo=excluded.paragrafo,
 documento_id=excluded.documento_id,pagina=excluded.pagina,conferido=excluded.conferido,
 status=case when excluded.status='vigencia_a_confirmar' then excluded.status else dispositivos.status end,
 metadata=dispositivos.metadata||excluded.metadata||jsonb_build_object('texto_anterior_curadoria',
 coalesce(dispositivos.metadata->'texto_anterior_curadoria',to_jsonb(dispositivos.texto_literal))), updated_at=now();

-- Links exatos recuperados em fonte primária. Um link não comprova vigência integral.
update public.normas set fonte_oficial='https://www.defesacivil.pr.gov.br/sites/defesa-civil/arquivos_restritos/files/documento/2025-07/portarian147.pdf' where titulo='Portaria nº 147 COLOG, de 21 de novembro de 2019' and fonte_oficial is null;
update public.normas set fonte_oficial='https://www.sgex.eb.mil.br/sg8/006_outras_publicacoes/07_publicacoes_diversas/01_comando_do_exercito/port_n_800_cmdo_eb_14ago2020.html' where titulo='Portaria nº 800, de 14 de agosto de 2020' and fonte_oficial is null;
do $guias$
declare g jsonb; sec jsonb; ref jsonb; secoes_guia jsonb; ids jsonb; dispositivo uuid; existente uuid;
begin
 for g in select value from jsonb_array_elements($dados$[{"titulo": "CNAE e classificação de risco da atividade", "pergunta_modelo": "O CNAE por si só dispensa o registro para atividade com PCE?", "produto": "todos", "atividade": "registro", "secoes": [{"titulo": "CNAE não resolve sozinho o enquadramento", "texto": "A Portaria 800 aprova uma tabela de risco de atividades sujeitas à liberação pelo SisFPC e determina sua revisão periódica. Ela estabelece que as atividades econômicas relacionadas a PCE não sejam classificadas no nível de risco I. Identifique o produto, a atividade efetiva e a linha aplicável da tabela; esta resposta não classifica um CNAE específico.", "referencias": [{"norma": "Portaria nº 800, de 14 de agosto de 2020", "referencia": "Art. 1º"}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "referencia": "Art. 2º"}, {"norma": "Portaria nº 800, de 14 de agosto de 2020", "referencia": "Art. 3º"}]}, {"titulo": "Registro da atividade", "texto": "O art. 7º, caput, do Anexo I estabelece registro para o exercício de atividades com PCE, próprio ou terceirizado. O código CNAE não comprova por si só uma dispensa; qualquer exceção depende da regra específica e de suas condições aplicáveis.", "referencias": [{"norma": "Decreto nº 10.030, de 30 de setembro de 2019", "referencia": "Anexo I, art. 7º, caput"}]}]}, {"titulo": "Registros empresariais de armas de fogo", "pergunta_modelo": "Quais dados e prazos de guarda se aplicam aos registros empresariais de armas de fogo?", "produto": "armas", "atividade": "todos", "secoes": [{"titulo": "Banco de dados e conservação", "texto": "O art. 16 das Normas da Portaria 213 exige banco próprio de fabricantes, pessoas jurídicas importadoras e comerciantes, com identificação do adquirente, autorização de aquisição, nota fiscal e, quando cabíveis, licença de importação e guia de tráfego. Os registros de armas devem ser mantidos por pelo menos vinte anos e suas informações disponibilizadas ao Exército, por intermédio da DFPC, e à Polícia Federal. Veja a transcrição para conferir todos os campos e as condições.", "referencias": [{"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 16, caput e §§ 1º a 3º"}]}, {"titulo": "Cadastro e comunicação", "texto": "O art. 17 trata do envio mensal pelos fabricantes e pessoas jurídicas importadoras para o cadastro no SICOFA; isso não estende automaticamente ao comerciante o procedimento de envio previsto para esses dois públicos. O art. 6º também determina que fabricante ou importador informe à DFPC o padrão serial utilizado.", "referencias": [{"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 17"}, {"norma": "Portaria nº 213 COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 6º"}]}]}, {"titulo": "Registros e estoques de munições", "pergunta_modelo": "Quais registros e prazos de guarda se aplicam ao comércio empresarial de munições?", "produto": "municoes", "atividade": "comercio", "secoes": [{"titulo": "Entradas, saídas e prazo", "texto": "O art. 9º das Normas da Portaria 214 exige banco próprio com os registros de entradas e saídas, incluindo dados do adquirente, produto, lote, documento fiscal, quantidade e os demais campos e condições ali previstos. Esses registros devem permanecer por pelo menos vinte anos à disposição da Administração Militar e dos órgãos de investigação policial. O dispositivo também prevê acesso para leitura e rastreamento; confira os destinatários e condições na transcrição.", "referencias": [{"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 9º, caput e §§ 1º a 4º"}]}, {"titulo": "Atualização de estoque", "texto": "O art. 11 determina que fabricantes, pessoas jurídicas importadoras e comerciantes cadastrem e atualizem os estoques de munições e seus insumos no SICOVEM. A regra do banco próprio e a atualização do estoque no sistema são obrigações distintas.", "referencias": [{"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 11"}]}]}, {"titulo": "Registros comerciais de insumos de munição", "pergunta_modelo": "Quais registros empresariais devem ser mantidos para insumos de munição?", "produto": "municoes", "atividade": "todos", "secoes": [{"titulo": "Dados, guarda e acesso", "texto": "O art. 10 das Normas da Portaria 214 exige banco próprio para entradas e saídas de insumos, define os dados e os insumos abrangidos e prevê guarda mínima de vinte anos. Também estabelece disponibilização para leitura e rastreamento. Esta orientação trata de registros administrativos; não fornece procedimentos de recarga.", "referencias": [{"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 10, caput e §§ 1º a 5º"}]}, {"titulo": "Estoque", "texto": "O art. 11 inclui os insumos na obrigação de cadastrar e atualizar estoques no SICOVEM. Confira o enquadramento do insumo antes de aplicar a obrigação ao produto específico.", "referencias": [{"norma": "Portaria nº 214-COLOG/C Ex, de 15 de setembro de 2021", "referencia": "Normas, art. 11"}]}]}, {"titulo": "Plano de segurança de PCE da empresa", "pergunta_modelo": "O que deve constar no plano de segurança de PCE da empresa?", "produto": "todos", "atividade": "todos", "secoes": [{"titulo": "Conteúdo e responsabilidade", "texto": "O art. 99 do Anexo I do Decreto 10.030 atribui à pessoa jurídica detentora de registro o planejamento e a implementação das medidas. O plano abrange análise de riscos, controle de acesso, proteção, prevenção durante deslocamentos e paradas, contingência e capacitação com registro. A empresa designa responsável; a execução pode ser terceirizada. O plano deve permanecer na sede, atualizado, legível e disponível à fiscalização quando solicitado.", "referencias": [{"norma": "Decreto nº 10.030, de 30 de setembro de 2019", "referencia": "Anexo I, art. 99, caput e §§ 1º a 3º"}]}, {"titulo": "Duas dimensões de segurança", "texto": "O art. 98 distingue segurança de área, relacionada a acidentes e integridade de pessoas e bens, de segurança de PCE, relacionada a desvios, extravios, roubos, furtos e aquisição ilícita de conhecimento. A orientação descreve o conteúdo normativo; não certifica a adequação de um plano concreto.", "referencias": [{"norma": "Decreto nº 10.030, de 30 de setembro de 2019", "referencia": "Anexo I, art. 98, caput e §§ 1º e 2º"}]}]}]$dados$::jsonb) loop
  secoes_guia:='[]'::jsonb;
  for sec in select value from jsonb_array_elements(g->'secoes') loop
   ids:='[]'::jsonb;
   for ref in select value from jsonb_array_elements(sec->'referencias') loop
    select d.id into dispositivo from public.dispositivos d join public.normas n on n.id=d.norma_id
    where n.titulo=ref->>'norma' and d.referencia=ref->>'referencia' and d.conferido and d.status in ('vigente','alterado');
    if dispositivo is null then raise exception 'Fundamento ausente ou pendente: %',ref; end if;
    ids:=ids||jsonb_build_array(dispositivo);
   end loop;
   secoes_guia:=secoes_guia||jsonb_build_array((sec-'referencias')||jsonb_build_object('dispositivo_ids',ids));
  end loop;
  select id into existente from public.orientacoes_empresariais where pergunta_modelo=g->>'pergunta_modelo';
  if existente is null then
   insert into public.orientacoes_empresariais(titulo,pergunta_modelo,produto,atividade,secoes,estado)
   values(g->>'titulo',g->>'pergunta_modelo',g->>'produto',g->>'atividade',secoes_guia,'publicada');
  else
   update public.orientacoes_empresariais set titulo=g->>'titulo',produto=g->>'produto',atividade=g->>'atividade',secoes=secoes_guia,estado='publicada' where id=existente;
  end if;
 end loop;
end $guias$;
create or replace function public.consultar_orientacao_pce(
 p_pergunta text,p_produto text default 'todos',p_atividade text default 'todos',
 p_publico text default 'empresa',p_data date default current_date
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare
 q text:=regexp_replace(trim(public.normalizar_pergunta_pce(p_pergunta)),'[[:space:]?!.,]+$','','g');
 modelo text; guia public.orientacoes_empresariais; refs text[]; fontes jsonb;
 produto text:=p_produto; atividade text:=p_atividade;
begin
 -- Primeiro a pergunta cadastrada: mantém o escopo aprovado pelo revisor.
 select o.* into guia from public.orientacoes_empresariais o where o.estado='publicada'
 and regexp_replace(trim(public.normalizar_pergunta_pce(o.pergunta_modelo)),'[[:space:]?!.,]+$','','g')=q
 order by o.id limit 1;
 if guia.id is null and q !~ 'prazo|quanto|validade|taxa|custo|document|dispens|isent|nao|exceto|percent|concentr|mistura|solucao|%|[0-9]|calibre|acido|nitrato|marca|modelo|somente|apenas|sem |spray|espargidor|munic|art[. ]|decreto|portaria|seguranca privada|escolta|umb|temporari' then
  if q ~ 'export' and q ~ 'produto(s)? controlado' and q ~ 'requisit|procedimento|como funciona' and q !~ 'import' then
   modelo:='Quais requisitos gerais se aplicam à exportação empresarial de PCE?';
  elsif q ~ 'fabric' and q ~ 'registro|registr' and q ~ 'como|procedimento' and q !~ 'comerci|import|export|transport|armazen' then
   modelo:='Como solicitar registro para fabricação de PCE?';
  elsif q ~ 'transport|trafeg' and q ~ 'produto(s)? controlado' and q ~ 'regra|requisit|norma' and q !~ 'import|export|armazen|comerci|fabric|adquir' then
   modelo:='Quais regras gerais se aplicam ao transporte empresarial de PCE?';
  elsif q ~ 'armazen' and q ~ 'produto(s)? controlado' and q ~ 'cuidado|regra|requisit|norma' and q !~ 'import|export|transport|comerci|fabric|adquir' then
   modelo:='Quais cuidados normativos se aplicam à armazenagem empresarial de PCE?';
  end if;
  if modelo is not null then select o.* into guia from public.orientacoes_empresariais o where o.estado='publicada' and o.pergunta_modelo=modelo order by o.id limit 1; end if;
 end if;
 if guia.id is null then return null; end if;
 if produto='todos' then
  produto:=case when q ~ 'explosiv' then 'explosivos' when q ~ 'quimic|mistura|solucao' then 'quimicos'
  when q ~ 'menor potencial|menos.letal' then 'menos_letais' when q ~ 'munic' then 'municoes' when q ~ 'armas? de fogo' then 'armas' else 'todos' end;
 end if;
 if atividade='todos' then atividade:=case
  when q ~ 'import|duimp' and q !~ 'export' then 'importacao'
  when q ~ 'export' and q !~ 'import' then 'exportacao'
  when q ~ 'transport|trafeg' and q !~ 'armazen' then 'transporte'
  when q ~ 'armazen' and q !~ 'transport' then 'armazenagem'
  when q ~ 'fabric' and q !~ 'nao fabricante' then 'fabricacao'
  when q ~ 'comerci|estoque|vendas' then 'comercio'
  when q ~ 'registro|registr|apostil|revalid' then 'registro' else 'todos' end; end if;
 if (guia.produto<>'todos' and guia.produto<>produto) or (guia.atividade<>'todos' and guia.atividade<>atividade) then return null; end if;
 select array_agg(distinct ref) into refs from jsonb_array_elements(guia.secoes) sec,
 jsonb_array_elements_text(sec->'dispositivo_ids') ref;
 if coalesce(cardinality(refs),0)=0 or exists(
  select 1 from unnest(refs) ref where not exists (
   select 1 from public.dispositivos d join public.normas n on n.id=d.norma_id where d.id::text=ref
   and d.conferido and d.status in ('vigente','alterado') and n.usar_como_fundamento
   and n.status in ('vigente','vigente_com_alteracoes','parcialmente_vigente')
   and (d.vigencia_inicio is null or d.vigencia_inicio<=p_data) and (d.vigencia_fim is null or d.vigencia_fim>=p_data)
   and (n.vigencia_inicio is null or n.vigencia_inicio<=p_data) and (n.vigencia_fim is null or n.vigencia_fim>=p_data))) then return null; end if;
 select jsonb_agg(jsonb_build_object(
 'trecho_id',d.id,'norma_id',n.id,'titulo',n.titulo,'dispositivo',d.referencia,'conteudo',d.texto_literal,
 'pagina',d.pagina,'relevancia',0,'status',n.status,'ultima_verificacao',n.ultima_verificacao,
 'dispositivo_id',d.id,'texto_literal',d.texto_literal,'status_dispositivo',d.status,'literal_conferido',d.conferido,
 'vigencia_inicio',d.vigencia_inicio,'vigencia_fim',d.vigencia_fim,'fonte_oficial',n.fonte_oficial,
 'nome_arquivo',doc.nome_arquivo,'sha256',doc.sha256,'tipo_conteudo','fundamento_orientacao',
 'relacoes','[]'::jsonb,'conferencia_textual',d.metadata->'conferencia_textual'
 ) order by array_position(refs,d.id::text),d.id) into fontes
 from public.dispositivos d join public.normas n on n.id=d.norma_id left join public.documentos doc on doc.id=d.documento_id
 where d.id::text=any(refs);
 return jsonb_build_object('fontes',fontes,'orientacoes',jsonb_build_array(to_jsonb(guia)),
 'data_referencia',p_data,'versao','empresas-v5-curadoria','fontes_excluidas',0,
 'pergunta_interpretada',case when modelo is not null then modelo else null end,'complementares',0);
end $$;
revoke execute on function public.consultar_orientacao_pce(text,text,text,text,date) from public;
grant execute on function public.consultar_orientacao_pce(text,text,text,text,date) to anon,authenticated;

create or replace function public.consultar_empresa_pce(
 p_pergunta text,p_produto text default 'todos',p_atividade text default 'todos',
 p_publico text default 'empresa',p_data date default current_date,p_limite integer default 10
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare resultado jsonb; fontes jsonb; revisada jsonb; interpretada text;
 q text:=public.normalizar_pergunta_pce(p_pergunta); produto_pergunta text; atividade_pergunta text;
begin
 resultado:=public.consultar_referencia_pce(p_pergunta,p_data);
 if resultado is null then
  produto_pergunta:=case when q ~ 'explosiv' then 'explosivos' when q ~ 'quimic|mistura|solucao' then 'quimicos'
   when q ~ 'menor potencial|menos.letal' then 'menos_letais' when q ~ 'munic' then 'municoes'
   when q ~ 'arma de fogo|armas de fogo' then 'armas' else 'todos' end;
  atividade_pergunta:=case when q ~ 'import|duimp' and q !~ 'export' then 'importacao'
   when q ~ 'export' and q !~ 'import' then 'exportacao'
   when q ~ 'transport|trafeg' and q !~ 'armazen|import|export' then 'transporte'
   when q ~ 'armazen' and q !~ 'transport|import|export' then 'armazenagem' else 'todos' end;
  if (p_produto<>'todos' and produto_pergunta<>'todos' and p_produto<>produto_pergunta)
   or (p_atividade not in ('todos','registro') and atividade_pergunta<>'todos' and p_atividade<>atividade_pergunta) then
   return jsonb_build_object('fontes','[]'::jsonb,'orientacoes','[]'::jsonb,'data_referencia',p_data,'versao','empresas-v5-curadoria','fontes_excluidas',0,
    'aviso_referencia','Os filtros selecionados contradizem o produto ou a operação mencionada. Ajuste a pergunta ou os filtros antes de consultar.');
  end if;
  resultado:=public.consultar_orientacao_pce(p_pergunta,p_produto,p_atividade,p_publico,p_data);
 end if;
 if resultado is null then
  resultado:=public.consultar_empresa_pce_v3(p_pergunta,p_produto,p_atividade,p_publico,p_data,p_limite);
  -- Se o modelo antigo reconheceu uma variação, tenta recuperar todos os fundamentos revisados.
  if resultado->>'pergunta_interpretada' is not null then
   interpretada:=resultado->>'pergunta_interpretada';
   revisada:=public.consultar_orientacao_pce(interpretada,p_produto,p_atividade,p_publico,p_data);
   if revisada is not null then resultado:=revisada||jsonb_build_object('pergunta_interpretada',interpretada); end if;
  end if;
 end if;
 select coalesce(jsonb_agg(f.value||jsonb_build_object('conferencia_textual',d.metadata->'conferencia_textual') order by f.ordinality),'[]'::jsonb)
 into fontes from jsonb_array_elements(resultado->'fontes') with ordinality f
 left join public.dispositivos d on d.id::text=f.value->>'dispositivo_id';
 return jsonb_set(resultado,'{fontes}',fontes);
end $$;


notify pgrst,'reload schema';
